EXTRA_SAFE_CHARS = b'|'

# Characters that are safe to keep verbatim in a URL (per RFC 3986) plus '%'
# so that already-percent-encoded octets are not encoded twice.
_safe_chars = RFC3986_RESERVED + RFC3986_UNRESERVED + EXTRA_SAFE_CHARS + b'%'

_ascii_tab_newline_re = re.compile(r'[\t\n\r]')


def to_unicode(data, encoding='utf-8', errors='strict'):
    """Return the unicode representation of a bytes object `data`."""
    if isinstance(data, six.text_type):
        return data
    if isinstance(data, six.binary_type):
        return data.decode(encoding, errors)
