def safe_url_string(url, encoding='utf8', path_encoding='utf8'):
    """Convert the given URL into a legal URL by escaping unsafe characters
    according to RFC-3986.

    If a bytes URL is given, it is first converted to `str` using the specified
    encoding, bytes that cannot be decoded are percent-encoded. UTF-8 encoding
    is used by default.
    """
    decoded = to_unicode(url, encoding=encoding, errors='percentencode')
    parts = urlsplit(_ascii_tab_newline_re.sub('', decoded))

    try:
        port = parts.port
    except ValueError:
        port = None

    netloc = ''
    if parts.username is not None or parts.password is not None:
        if parts.username is not None:
            netloc += quote(parts.username.encode(encoding), _safe_chars)
        if parts.password is not None:
            netloc += ':' + quote(parts.password.encode(encoding), _safe_chars)
        netloc += '@'
    if parts.hostname:
        try:
            netloc += parts.hostname.encode('idna').decode('ascii')
        except UnicodeError:
            netloc += parts.hostname
