        netloc += ':%d' % port

    return urlunsplit((
        parts.scheme,
        netloc,
        quote(parts.path.encode(path_encoding), _safe_chars),
        quote(parts.query.encode(encoding), _safe_chars),
        quote(parts.fragment.encode(encoding), _safe_chars),
